mapper.select:
SELECT pi.instance_id AS processInstanceId, biz.business_type AS businessType, biz.business_id AS businessId, 'COMPLETED' AS expectedStatus, biz.actual_status AS actualStatus, biz.tenant_id AS tenantId FROM wf_process_instance pi JOIN (
SELECT ${bt.processInstanceIdField} AS process_instance_id, '${bt.code}' AS business_type, ${bt.idField} AS business_id, ${bt.statusField} AS actual_status, ${bt.businessTable}.tenant_id AS tenant_id FROM ${bt.businessTable} WHERE ${bt.statusField} IN ('PENDING','APPROVING') AND ${bt.processInstanceIdField} IS NOT NULL
) biz ON pi.instance_id = biz.process_instance_id AND pi.tenant_id = biz.tenant_id WHERE pi.status = 'COMPLETED' AND pi.end_time >= DATE_SUB(NOW(), INTERVAL #{windowMinutes} MINUTE)
